content.text:
:root {
  --bg-color: #2c2c2c;
  --text-color: white;
  --toggle-bg: #555;
  --toggle-thumb-color: white;
  --thumb-left: 2px;
  --graph-bg: #1f1f1f;
}

[data-theme="light"] {
  --bg-color: white;
  --text-color: black;
  --toggle-bg: #ddd;
  --toggle-thumb-color: #333;
  --thumb-left: 26px;
  --graph-bg: white;
}

body {
  margin: 0 !important;
  padding: 0 !important;
  overflow-x: hidden;
  background-color: var(--bg-color) !important;
}

#app-container {
  background-color: var(--bg-color);
  color: var(--text-color);
  transition: background-color 0.3s;
  min-height: 100vh;
}

#header-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 20px 0 20px;
}

#header-wrapper {
  background-color: var(--bg-color);
  margin: 0;
  padding: 0;
}

#dash-title {
  color: var(--text-color);
  margin: 0;
  padding: 10px 0;
}

#gain-summary-wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
}

#gain-summary {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  width: 100%;
  text-align: center;
  flex-wrap: wrap;
  color: var(--text-color);
}

#separator {
  display: inline-block;
  width: 15px;
}

#total-value-span {
  color: var(--text-color);
}

#theme-toggle {
  width: 50px;
  height: 26px;
  background-color: var(--toggle-bg);
  border-radius: 50px;
  position: relative;
  cursor: pointer;
  transition: background-color 0.3s;
}

#toggle-thumb {
  width: 22px;
  height: 22px;
  background-color: var(--toggle-thumb-color);
  border-radius: 50%;
  position: absolute;
  left: var(--thumb-left);
  top: 2px;
  transition: left 0.3s, background-color 0.3s;
}

.graph-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  width: 100%;
  box-sizing: border-box;
  padding: 0 10px;
  margin-top: 5px;
}

.graph-wrapper {
  width: 100%;
  min-width: 0;
}

.graph-wrapper .js-plotly-plot {
  width: 100%;
}

/* Force app-level backgrounds to theme color */
html, body, #app-container {
  background-color: var(--bg-color) !important;
  color: var(--text-color);
}

/* Dash renders extra wrapper divs (e.g. around tabs) with default white backgrounds */
#react-entry-point,
#react-entry-point > div,
#_dash-app-content,
#_dash-app-content > div,
#app-container > div {
  background-color: var(--bg-color) !important;
}

/* Preserve Plotly graph containers so chart paper_bgcolor is respected */
.js-plotly-plot,
.js-plotly-plot .plotly,
.js-plotly-plot .svg-container {
  background-color: transparent !important;
}

/* Dash Tabs - theme all wrapper divs inside main-tabs.
   Tab buttons keep their inline callback styles because
   inline specificity (1000) beats this selector. */
#main-tabs,
#main-tabs > div,
#main-tabs > div > div,
#main-tabs > div > div > div {
  background-color: var(--bg-color);
}

/* Tab button borders only (backgrounds come from callback inline styles) */
#main-tabs .tab,
#main-tabs [class*="tab"]:not([class*="content"]):not([class*="container"]) {
  border: none !important;
  border-bottom: 2px solid transparent !important;
}

#main-tabs .tab--selected,
#main-tabs [class*="--selected"] {
  border-bottom: 2px solid #4caf50 !important;
}

.apply-container {
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-width: 1000px;
  margin: 20px auto;
  padding: 0 10px;
}

.apply-textarea {
  background-color: var(--graph-bg);
  color: var(--text-color);
  border: 1px solid var(--toggle-bg);
  border-radius: 6px;
  padding: 10px;
  font-family: monospace;
  resize: vertical;
}

.apply-button {
  align-self: flex-start;
  padding: 10px 20px;
  background-color: #4caf50;
  color: white;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  font-size: 16px;
  transition: background-color 0.2s;
}

.apply-button:hover {
  background-color: #45a049;
}

.apply-button:active {
  background-color: #3e8e41;
}

/* Average Monthly Gain tile - placed inside #gain-summary, wraps as needed */
.avg-monthly-gain-window {
  vertical-align: middle;
}

.avg-monthly-gain-window .Select-control {
  background-color: var(--toggle-bg);
  border-color: var(--toggle-bg);
  color: var(--text-color);
}

.avg-monthly-gain-window .Select-value-label,
.avg-monthly-gain-window .Select-placeholder {
  color: var(--text-color) !important;
}

.avg-monthly-gain-window .Select-menu-outer {
  background-color: var(--toggle-bg);
  color: var(--text-color);
  border-color: var(--toggle-bg);
}

.avg-monthly-gain-window .Select-option {
  background-color: var(--toggle-bg);
  color: var(--text-color);
}

.avg-monthly-gain-window .Select-option.is-focused {
  background-color: #4caf50;
  color: white;
}

[data-theme="light"] .avg-monthly-gain-window .Select-control,
[data-theme="light"] .avg-monthly-gain-window .Select-menu-outer,
[data-theme="light"] .avg-monthly-gain-window .Select-option {
  background-color: #ddd;
  color: black;
}

[data-theme="light"] .apply-textarea {
  background-color: white;
  color: black;
  border: 1px solid #ccc;
}

/* Purchases table styling */
.purchases-table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 1rem;
  font-family: inherit;
}

.purchases-table th,
.purchases-table td {
  border: 1px solid #444;
  padding: 8px 12px;
  text-align: left;
}

.purchases-table th {
  background-color: #555;
  color: white;
  font-weight: 600;
}

.purchases-table tbody tr:nth-child(even) {
  background-color: #3a3a3a;
}

.purchases-table tbody tr:nth-child(odd) {
  background-color: #2c2c2c;
}

.purchases-table td {
  color: white;
}

[data-theme="light"] .purchases-table th {
  background-color: #ddd;
  color: black;
  border-color: #bbb;
}

[data-theme="light"] .purchases-table td {
  color: black;
  border-color: #bbb;
}

[data-theme="light"] .purchases-table tbody tr:nth-child(even) {
  background-color: #f5f5f5;
}

.toggle-button {
  align-self: flex-start;
  padding: 5px 15px;
  background-color: var(--toggle-bg);
  color: var(--text-color);
  border: 1px solid #444;
  border-radius: 6px;
  cursor: pointer;
  margin-bottom: 10px;
  font-size: 14px;
  transition: background-color 0.2s;
}

.toggle-button:hover {
  filter: brightness(1.2);
}

@media (max-width: 768px) {
  .graph-grid {
    grid-template-columns: 1fr;
  }
}

